zhPhrases['Parsed']='已读取';
const zhEntries=Object.entries(zhPhrases).sort((a,b)=>b[0].length-a[0].length);
function toZh(value){for(const [from,to] of zhEntries)value=value.split(from).join(to);return value}
function translateTree(root=document.body){if(root.nodeType===3){const translated=toZh(root.nodeValue);if(translated!==root.nodeValue)root.nodeValue=translated;return}const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){const converted=toZh(node.nodeValue);if(converted!==node.nodeValue)node.nodeValue=converted}if(root.nodeType===1){for(const attr of ['placeholder','aria-label','title'])if(root.hasAttribute(attr)){const v=toZh(root.getAttribute(attr));if(v!==root.getAttribute(attr))root.setAttribute(attr,v)}if(root.matches?.('textarea'))root.value=toZh(root.value);if(root.matches?.('input')&&root.value)root.value=toZh(root.value);for(const el of root.querySelectorAll?.('textarea,input[placeholder],button[aria-label]')||[]){if(el.matches('textarea'))el.value=toZh(el.value);if(el.matches('input')&&el.value)el.value=toZh(el.value);for(const attr of ['placeholder','aria-label','title'])if(el.hasAttribute(attr))el.setAttribute(attr,toZh(el.getAttribute(attr)))}}}
document.title='AI 费用报销审核 · 中文演示';translateTree();new MutationObserver(records=>records.forEach(r=>{if(r.type==='characterData'){const v=toZh(r.target.nodeValue);if(v!==r.target.nodeValue)r.target.nodeValue=v}else r.addedNodes.forEach(n=>{if(n.nodeType===1||n.nodeType===3)translateTree(n)})})).observe(document.body,{subtree:true,childList:true,characterData:true});

let receiptPhoto=null,receiptPhotoUrl=null,cameraStream=null;
function attachReceipt(file){if(!file)return;if(!file.type.startsWith('image/')){toast('文件格式不支持','请选择 JPG、PNG 或 HEIC 图片');return}if(receiptPhotoUrl)URL.revokeObjectURL(receiptPhotoUrl);receiptPhoto=file;receiptPhotoUrl=URL.createObjectURL(file);renderFiles(cases[current]);toast('票据照片已添加',file.name+' 已作为当前报销单的附件')}
const renderFilesOriginal=renderFiles;
renderFiles=function(data){renderFilesOriginal(data);if(!receiptPhoto)return;const card=document.createElement('div');card.className='file';const top=document.createElement('div');top.className='file-top';top.innerHTML='<span class="file-type">IMG</span><span>✓ '+toZh('Parsed')+'</span>';const name=document.createElement('strong');name.textContent=receiptPhoto.name;const img=document.createElement('img');img.className='photo-preview';img.src=receiptPhotoUrl;img.alt='拍摄或上传的票据预览';card.append(top,name,img);$('#files').append(card);const count=$('#fileCount');if(count)count.textContent='· '+(data.files.length+1)+' 个文件'};
const receiptFileInput=$('#receiptPhotoInput'),receiptCaptureInput=$('#receiptCameraInput');
$('#receiptUpload').onclick=()=>receiptFileInput.click();receiptFileInput.onchange=e=>{attachReceipt(e.target.files[0]);e.target.value=''};receiptCaptureInput.onchange=e=>{attachReceipt(e.target.files[0]);e.target.value=''};
async function openReceiptCamera(){if(!navigator.mediaDevices?.getUserMedia){receiptCaptureInput.click();return}try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});$('#receiptVideo').srcObject=cameraStream;$('#receiptCameraModal').classList.add('open')}catch(e){toast('无法打开相机','请允许相机权限，或选择上传图片');receiptCaptureInput.click()}}
$('#receiptOpenCamera').onclick=()=>{if(matchMedia('(max-width: 700px)').matches)receiptCaptureInput.click();else openReceiptCamera()};
function closeReceiptCamera(){if(cameraStream){cameraStream.getTracks().forEach(track=>track.stop());cameraStream=null}$('#receiptCameraModal').classList.remove('open')}
$('#closeReceiptCamera').onclick=closeReceiptCamera;$('#receiptCameraModal').onclick=e=>{if(e.target===$('#receiptCameraModal'))closeReceiptCamera()};$('#captureReceipt').onclick=()=>{const v=$('#receiptVideo'),c=document.createElement('canvas');if(!v.videoWidth){toast('相机正在启动','请稍候再拍摄');return}c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);c.toBlob(blob=>{if(blob)attachReceipt(new File([blob],'receipt-photo.jpg',{type:'image/jpeg'}));closeReceiptCamera()},'image/jpeg',.92)};
const showResultOriginal=showResult;
showResult=function(){showResultOriginal();if(!receiptPhoto)return;const check=document.createElement('div');check.className='check ok';check.innerHTML='<div class="check-icon">✓</div><div><strong>已附加票据影像</strong><small></small></div><a>已纳入演示凭证</a>';check.querySelector('small').textContent=receiptPhoto.name;$('#checks').append(check);const existing=$('#note').innerHTML;$('#note').innerHTML='<b>票据照片：</b>已附加到当前报销单，并作为凭证展示。此页面沿用演示案例的预设审核结果，不会对照片执行真实 OCR。<br>'+existing};
const viewFilesOriginal=$('#viewFiles').onclick;$('#viewFiles').onclick=()=>{if(receiptPhotoUrl){window.open(receiptPhotoUrl,'_blank','noopener');return}viewFilesOriginal?.()};
